ee:variables.ee:set-variable:
%dw 2.0
import * from statsvc::api
output application/java
var r = vars.r
var dims = p('stat.dims') as Number
---
if (r.method == 'GET' and r.path == '/') describe(r.serve)
else if (r.method == 'GET' and r.path == '/health') ok({status: 'ok'})
else if (not r.ok) fail(r.kind, 401, if (r.kind == 'ollama') 'unauthorized'
                                     else if (r.kind == 'azure') 'Access denied due to invalid subscription key or wrong API endpoint.'
                                     else 'Incorrect API key provided.')
else if (r.embed and r.method == 'POST' and (['/v1/embeddings', '/embeddings', '/openai/v1/embeddings'] contains r.path))
    openaiEmbed(payload, payload.model default 'hash512', dims, r.kind)
else if (r.embed and r.method == 'POST' and r.deployment != null) openaiEmbed(payload, r.deployment, dims, 'azure')
else if (r.embed and r.method == 'POST' and r.path == '/api/embeddings') ollamaLegacy(payload)
else if (r.embed and r.method == 'POST' and r.path == '/api/embed') ollamaEmbed(payload, dims)
else if (r.embed and r.method == 'GET' and r.path == '/api/tags') ollamaTags()
else if (r.llm and r.method == 'POST' and (['/v1/chat/completions', '/chat/completions'] contains r.path))
    chat(payload, {threshold: p('stat.threshold') as Number, noAnswer: p('stat.noAnswer')},
         'chatcmpl-stat-' ++ uuid(), now() as Number {unit: 'seconds'})
else if (r.method == 'GET' and (['/v1/models', '/models'] contains r.path)) models(r.serve)
else fail(r.kind, 404, 'Unknown request URL: ' ++ r.method ++ ' ' ++ r.path)
